        "BankCard.allInstance()->select(o|o.CardID=InputCard.CardIDando.Password=InputCard.Password)",
    }).build().pass;
    let cardMatch: boolean = l({
      logic: () =>
        obs.forEach(
          (o: BankCard) =>
            l({
