        "obs->forAll(o:BankCard|o.CardID=InputCard.CardIDando.Password=InputCard.Password)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
